//! Compiled-code probes: a handle on the executable Rust behind a modeled requirement or
//! calculation, generated by `#[sysml::requirement]` / `#[sysml::calc]` and collected per
//! package by `#[sysml::package]` (`sysml_compiled_probes()`).
//!
//! They exist so tests can check that the IR expression evaluator (`sysml_emit::expr_eval`),
//! which only sees the emitted SysML strings, agrees with the compiled
//! `EvaluableRequirement::evaluate()` / `#[sysml::calc] fn` on the same values. They are not
//! part of the modeling surface.

/// Attribute value lookup by SysML name (`None` keeps the compiled default).
pub type ValueLookup<'a> = &'a dyn Fn(&str) -> Option<f64>;

/// Evaluate a compiled requirement with attribute values chosen by name.
#[derive(Clone)]
pub struct RequirementProbe {
    /// SysML name of the `requirement def`.
    pub name: &'static str,
    /// The `require constraint` strings that the compiled `evaluate()` checks (string-literal
    /// constraints are emitted but not compiled, so they are not listed).
    pub constraints: &'static [&'static str],
    /// Build `Default::default()`, overwrite every scalar attribute for which `lookup(sysml
    /// attribute name)` is `Some`, then call `evaluate()`.
    pub eval: fn(ValueLookup<'_>) -> bool,
}

/// Call a compiled `#[sysml::calc] fn` with numeric arguments.
#[derive(Clone)]
pub struct CalcProbe {
    /// SysML name of the `calc def`.
    pub name: &'static str,
    pub arity: usize,
    pub eval: fn(&[f64]) -> f64,
}

/// Every probe of one package (nested packages included).
#[derive(Clone, Default)]
pub struct CompiledProbes {
    pub requirements: Vec<RequirementProbe>,
    pub calcs: Vec<CalcProbe>,
}

impl CompiledProbes {
    pub fn extend(&mut self, other: CompiledProbes) {
        self.requirements.extend(other.requirements);
        self.calcs.extend(other.calcs);
    }
}
